import type { RevertChoice, RevertCost, RevertInput, RevertItem } from "./types.js";

/** Inputs to one cost evaluation; indices are transcript positions. */
export interface RevertCostInput {
  readonly nodes: readonly RevertItem[];
  /** Node indices whose verdict is `forget`. */
  readonly forgotten: ReadonlySet<number>;
  /** Nodes [0, cutIndex) stay verbatim; nothing before the cut is re-paid. */
  readonly cutIndex: number;
  /** Generated bytes a receipt for one forgotten index costs. */
  readonly receiptBytes: (index: number) => number;
}

/**
 * Salvage arithmetic for one cut (design-protocol §2), transcribed:
 *
 *   freed(c)   = Σ byteLength(i)   for i ≥ c and i ∈ forgotten
 *   kept(c)    = Σ byteLength(i)   for i ≥ c and i ∉ forgotten
 *   receipt(c) = Σ receiptBytes(i) for i ≥ c and i ∈ forgotten
 *   net(c)     = freed(c) − kept(c) − receipt(c)
 *
 * Pure: no snapshot, clock, archive or ledger. Nodes before the cut are never
 * in a sum — they survive untouched. Both the kept suffix and the receipts
 * count as costs because both are paid again in full: the survivors are
 * re-appended and every receipt is generated bytes.
 */
export function revertCost(input: RevertCostInput): RevertCost {
  assertItems(input.nodes);
  const cutIndex = input.cutIndex;
  if (!Number.isSafeInteger(cutIndex) || cutIndex < 0 || cutIndex > input.nodes.length) {
    throw new Error(`Revert cut index ${cutIndex} is outside the transcript`);
  }
  const sums = suffixSums(input.nodes, input.forgotten, input.receiptBytes, cutIndex);
  const freedBytes = sums.freed[cutIndex] ?? 0;
  const keptBytes = sums.kept[cutIndex] ?? 0;
  const receiptBytes = sums.receipts[cutIndex] ?? 0;
  return {
    cutIndex,
    freedBytes,
    keptBytes,
    receiptBytes,
    netFreedBytes: freedBytes - keptBytes - receiptBytes,
  };
}

/**
 * Picks the cut that maximises `net(c)` over
 * `candidates = { i ∈ forgotten | i ≥ freshStart }` (design-protocol §2).
 *
 * Both filters apply: `freed(c) ≥ minCutFreedBytes` skips small early cuts,
 * and `net(c) > 0` refuses a cut whose kept suffix plus receipts outweigh the
 * freed bytes. Candidates are visited in ascending index order and a candidate
 * replaces the incumbent only on a strictly larger net, so a tie keeps the
 * **smaller** `cutIndex` — maximum salvage, and the same answer for the same
 * input on every run. No candidate passing both filters yields `null`.
 */
export function chooseRevertCut(input: RevertInput): RevertChoice | null {
  const nodes = input.nodes;
  assertItems(nodes);
  if (!Number.isSafeInteger(input.minCutFreedBytes) || input.minCutFreedBytes < 0) {
    throw new Error("minCutFreedBytes must be a non-negative safe integer");
  }
  const freshStart = normalizeFreshStart(input.freshStart, nodes.length);
  // The same suffix sums `revertCost` reads, built once for the whole scan.
  const sums = suffixSums(nodes, input.forgotten, input.receiptBytes, freshStart);
  let best: RevertChoice | null = null;
  for (let cutIndex = freshStart; cutIndex < nodes.length; cutIndex++) {
    // Only a forgotten node can be a cut; anything else is not a candidate.
    if (!input.forgotten.has(cutIndex)) continue;
    const freedBytes = sums.freed[cutIndex] ?? 0;
    const keptBytes = sums.kept[cutIndex] ?? 0;
    const receiptBytes = sums.receipts[cutIndex] ?? 0;
    const cost: RevertCost = {
      cutIndex,
      freedBytes,
      keptBytes,
      receiptBytes,
      netFreedBytes: freedBytes - keptBytes - receiptBytes,
    };
    if (cost.freedBytes < input.minCutFreedBytes) continue;
    if (cost.netFreedBytes <= 0) continue;
    // Strict `>`: a tie keeps the earlier candidate, i.e. the smaller cut.
    if (best === null || cost.netFreedBytes > best.cost.netFreedBytes) {
      best = { cutIndex, cost };
    }
  }
  return best;
}

/** The §2 sums from `fromIndex` to the end of the transcript, in one pass. */
interface SuffixSums {
  readonly freed: readonly number[];
  readonly kept: readonly number[];
  readonly receipts: readonly number[];
}

function suffixSums(
  nodes: readonly RevertItem[],
  forgotten: ReadonlySet<number>,
  receiptBytes: (index: number) => number,
  fromIndex: number,
): SuffixSums {
  const length = nodes.length;
  const freed = new Array<number>(length + 1).fill(0);
  const kept = new Array<number>(length + 1).fill(0);
  const receipts = new Array<number>(length + 1).fill(0);
  for (let index = length - 1; index >= fromIndex; index--) {
    const item = nodes[index];
    if (item === undefined) continue; // unreachable: index < length
    const isForgotten = forgotten.has(index);
    freed[index] = (freed[index + 1] ?? 0) + (isForgotten ? item.byteLength : 0);
    kept[index] = (kept[index + 1] ?? 0) + (isForgotten ? 0 : item.byteLength);
    receipts[index] = (receipts[index + 1] ?? 0)
      + (isForgotten ? receiptFor(receiptBytes, index) : 0);
  }
  return { freed, kept, receipts };
}

/** Reads one receipt cost; a malformed value would corrupt every sum silently. */
function receiptFor(receiptBytes: (index: number) => number, index: number): number {
  const bytes = receiptBytes(index);
  if (!Number.isSafeInteger(bytes) || bytes < 0) {
    throw new Error(`Receipt bytes for index ${index} must be a non-negative safe integer`);
  }
  return bytes;
}

/** Rejects a byte length that would make the arithmetic meaningless. */
function assertItems(nodes: readonly RevertItem[]): void {
  for (const item of nodes) {
    if (!Number.isSafeInteger(item.byteLength) || item.byteLength < 0) {
      throw new Error(`Revert item ${item.nodeId} has an invalid byte length`);
    }
  }
}

/** A fresh-zone start outside the transcript is clamped, never a silent crash. */
function normalizeFreshStart(freshStart: number, length: number): number {
  if (!Number.isSafeInteger(freshStart)) {
    throw new Error("freshStart must be a safe integer");
  }
  return Math.min(Math.max(freshStart, 0), length);
}
